mapper.select:
SELECT  ID                                              AS "id"
       ,SENDER_ID                                       AS "senderId"
       ,BODY                                            AS "body"
       ,(EXTRACT(EPOCH FROM INS_DAY) * 1000)::BIGINT    AS "at"
  FROM T_DM_MSG
 WHERE 1=1
   AND ROOM_ID = #{roomId}
   AND ID < #{before}
 ORDER BY ID DESC
 LIMIT #{limit}

mapper.update:
UPDATE T_DM_ROOM
   SET LAST_MSG_ID = #{msgId}
      ,LAST_AT     = NOW()
      ,READ_A = GREATEST(READ_A, #{msgId})
      ,READ_B = GREATEST(READ_B, #{msgId})
 WHERE ID = #{roomId}
